from __future__ import annotations

import base64
import contextlib
import datetime
import hashlib
import io
import json
import os
import shutil
import ssl
import sys
import subprocess
import tempfile
from pathlib import Path

class SimpleIdentity:

    def __init__(self, key_pem: bytes, cert_pem: bytes) -> None:
        self.key_pem = key_pem if isinstance(key_pem, bytes) else key_pem.encode("utf-8")
        self.cert_pem = cert_pem if isinstance(cert_pem, bytes) else cert_pem.encode("utf-8")
        der = ssl.PEM_cert_to_DER_cert(self.cert_pem.decode("utf-8"))
        self.fingerprint = hashlib.sha256(der).hexdigest()
        self.fp_b64 = base64.b64encode(hashlib.sha256(der).digest()).decode("ascii")

def _generate_cert_cryptography(key_p: Path, cert_p: Path) -> bool:
    try:
        from cryptography import x509
        from cryptography.hazmat.primitives import hashes, serialization
        from cryptography.hazmat.primitives.asymmetric import rsa
        from cryptography.x509.oid import NameOID

        key = rsa.generate_private_key(public_exponent=65537, key_size=2048)
        subject = issuer = x509.Name([x509.NameAttribute(NameOID.COMMON_NAME, "samyuj")])
        now = datetime.datetime.now(datetime.UTC)
        cert = (
            x509.CertificateBuilder()
            .subject_name(subject)
            .issuer_name(issuer)
            .public_key(key.public_key())
            .serial_number(x509.random_serial_number())
            .not_valid_before(now - datetime.timedelta(days=1))
            .not_valid_after(now + datetime.timedelta(days=3650))
            .sign(key, hashes.SHA256())
        )
        key_bytes = key.private_bytes(
            encoding=serialization.Encoding.PEM,
            format=serialization.PrivateFormat.TraditionalOpenSSL,
            encryption_algorithm=serialization.NoEncryption(),
        )
        kfd = os.open(str(key_p), os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o600)
        try:
            with contextlib.suppress(OSError):
                os.fchmod(kfd, 0o600)
            os.write(kfd, key_bytes)
        finally:
            os.close(kfd)
        cert_p.write_bytes(cert.public_bytes(serialization.Encoding.PEM))
        with contextlib.suppress(OSError):
            os.chmod(cert_p, 0o600)
        return True
    except Exception:
        return False

def load_or_create_identity(state_dir: str | Path) -> SimpleIdentity:
    d = Path(state_dir)
    d.mkdir(parents=True, mode=0o700, exist_ok=True)
    key_p, cert_p = d / "identity.key.pem", d / "identity.cert.pem"
    if key_p.exists() and cert_p.exists():
        return SimpleIdentity(key_p.read_bytes(), cert_p.read_bytes())
    if not _generate_cert_cryptography(key_p, cert_p):
        if not shutil.which("openssl"):
            raise RuntimeError("Neither cryptography nor openssl CLI is available to mint TLS identity")
        subprocess.run(
            [
                "openssl", "req", "-x509", "-newkey", "rsa:2048",
                "-keyout", str(key_p), "-out", str(cert_p),
                "-days", "3650", "-nodes", "-subj", "/CN=samyuj",
            ],
            check=True,
            capture_output=True,
            timeout=15.0,
        )
    with contextlib.suppress(OSError):
        os.chmod(key_p, 0o600)
        os.chmod(cert_p, 0o600)
    return SimpleIdentity(key_p.read_bytes(), cert_p.read_bytes())

def fingerprint_b64(ident: SimpleIdentity) -> str:
    der = ssl.PEM_cert_to_DER_cert(ident.cert_pem.decode("utf-8"))
    return base64.b64encode(hashlib.sha256(der).digest()).decode("ascii")

def make_server_ssl_context(ident: SimpleIdentity) -> ssl.SSLContext:
    ctx = ssl.SSLContext(ssl.PROTOCOL_TLS_SERVER)
    ctx.minimum_version = ssl.TLSVersion.TLSv1_2
    with contextlib.suppress(ssl.SSLError):
        ctx.set_ciphers("DEFAULT:@SECLEVEL=0")
    with tempfile.NamedTemporaryFile(suffix=".pem", delete=False) as f:
        with contextlib.suppress(OSError):
            os.fchmod(f.fileno(), 0o600)
        c_b = ident.cert_pem.encode() if isinstance(ident.cert_pem, str) else ident.cert_pem
        k_b = ident.key_pem.encode() if isinstance(ident.key_pem, str) else ident.key_pem
        f.write(c_b.rstrip() + b"\n" + k_b)
        chain = f.name
    try:
        ctx.load_cert_chain(chain)
    finally:
        with contextlib.suppress(OSError):
            os.unlink(chain)
    return ctx

def make_client_ssl_context(cert_pem: bytes | None = None, key_pem: bytes | None = None) -> ssl.SSLContext:
    ctx = ssl.SSLContext(ssl.PROTOCOL_TLS_CLIENT)
    ctx.check_hostname = False
    ctx.verify_mode = ssl.CERT_NONE
    ctx.minimum_version = ssl.TLSVersion.TLSv1_2
    with contextlib.suppress(ssl.SSLError):
        ctx.set_ciphers("DEFAULT:@SECLEVEL=0")
    if cert_pem and key_pem:
        with tempfile.NamedTemporaryFile(suffix=".pem", delete=False) as f:
            with contextlib.suppress(OSError):
                os.fchmod(f.fileno(), 0o600)
            f.write(cert_pem.rstrip() + b"\n" + key_pem)
            chain = f.name
        try:
            ctx.load_cert_chain(chain)
        finally:
            with contextlib.suppress(OSError):
                os.unlink(chain)
    return ctx

def load_or_create_device_id(state_dir: str | Path) -> str:
    d = Path(state_dir)
    d.mkdir(parents=True, mode=0o700, exist_ok=True)
    p = d / "device_id.txt"
    if p.exists():
        val = p.read_text(encoding="utf-8").strip()
        if val:
            return val
    v = base64.b64encode(os.urandom(16)).decode("ascii")
    p.write_text(v, encoding="utf-8")
    with contextlib.suppress(OSError):
        os.chmod(p, 0o600)
    return v

def build_qr_payload_str(
    ips: list[str],
    port: int,
    fp_b64: str,
    token_b64: str,
    device_id_b64: str,
    ver: int = 3,
) -> str:
    clean_ips = [ip for ip in ips if ip and not ip.startswith("127.")] or ["127.0.0.1"]
    payload_obj = {
        "ver": int(ver),
        "ips": clean_ips,
        "port": int(port),
        "fp": str(fp_b64),
        "token": str(token_b64),
        "deviceId": str(device_id_b64),
    }
    return "R4:" + json.dumps(payload_obj, separators=(",", ":"))

