_segno_ready = False
SCRIPT_DIR = Path(__file__).resolve().parent
REPO_ROOT = Path(__file__).resolve().parents[3]

def _ensure_segno() -> bool:
    global _segno_ready
    if _segno_ready:
        return True
    try:
        import segno
        _segno_ready = True
        return True
    except ImportError:
        pass
    for cand in (SCRIPT_DIR / "vendor", REPO_ROOT / "vendor"):
        with contextlib.suppress(OSError):
            if (cand / "segno").is_dir() or (cand / "segno.py").is_file():
                if str(cand) not in sys.path:
                    sys.path.insert(0, str(cand))
                try:
                    import segno
                    _segno_ready = True
                    return True
                except ImportError:
                    continue
    if _SEGNO_ZIP_B85 and not _SEGNO_ZIP_B85.startswith("@@"):
        with contextlib.suppress(Exception):
            raw = base64.b85decode(_SEGNO_ZIP_B85.encode("ascii"))
            want_digest = hashlib.sha256(raw).digest()
            cache_base = Path(os.environ.get("XDG_CACHE_HOME") or (Path.home() / ".cache")) / "samyuj" / "vendor"
            try:
                cache_base.mkdir(parents=True, mode=0o700, exist_ok=True)
                os.chmod(cache_base, 0o700)
            except OSError:
                cache_base = Path(tempfile.gettempdir()) / f"samyuj-vendor-{os.getuid()}"
                cache_base.mkdir(parents=True, mode=0o700, exist_ok=True)
                os.chmod(cache_base, 0o700)
            st_dir = os.lstat(cache_base)
            if st_dir.st_uid != os.getuid() or cache_base.is_symlink():
                return False
            zpath = cache_base / "samyuj_embedded_segno.zip"
            valid_existing = False
            if zpath.is_file() and not zpath.is_symlink():
                with contextlib.suppress(OSError):
                    if hashlib.sha256(zpath.read_bytes()).digest() == want_digest:
                        valid_existing = True
            if not valid_existing:
                tmp_z = cache_base / f"segno_{os.getpid()}.tmp"
                fd = os.open(str(tmp_z), os.O_WRONLY | os.O_CREAT | os.O_TRUNC | getattr(os, "O_NOFOLLOW", 0), 0o600)
                try:
                    os.write(fd, raw)
                finally:
                    os.close(fd)
                os.replace(tmp_z, zpath)
            if str(zpath) not in sys.path:
                sys.path.append(str(zpath))
            import segno
            _segno_ready = True
            return True
    return False

def render_qr_png(payload: str, ec: str = "m") -> bytes | None:
    if not payload:
        return None
    if _ensure_segno():
        with contextlib.suppress(Exception):
            import segno

        buf = io.BytesIO()
        segno.make(payload, error=ec).save(buf, kind="png", scale=9, border=3)
        return buf.getvalue()
    with contextlib.suppress(Exception):
        import qrcode

        img = qrcode.make(payload, box_size=15)
        buf = io.BytesIO()
        img.save(buf, format="PNG")
        return buf.getvalue()
    return None

def render_qr_ascii(payload: str, ec: str = "m") -> str:
    if not payload:
        return ""
    if _ensure_segno():
        with contextlib.suppress(Exception):
            import segno

        out = io.StringIO()
        segno.make(payload, error=ec).terminal(out=out, border=2, compact=True)
        return out.getvalue()
    return ""
